CREATE OR REPLACE FUNCTION public.extrair_faixa_etaria(texto text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_min TEXT;
    v_max TEXT;
    v_lim_f TEXT;
BEGIN
    -- 1) Faixas explícitas: 10-17, 10/17, 10 a 17, 10A17
    SELECT
        m[1], m[2]
    INTO
        v_min, v_max
    FROM regexp_matches(
        texto,
        '(?<!\d)(\d{2})\s*(?:-|/|A|a|\s+a\s+)\s*(\d{2})(?!\d)'
    ) AS m
    LIMIT 1;

    IF v_min > v_max THEN
        RETURN null;
    end if;

    if v_max = '99' THEN
        v_lim_f := ']';
    else
        if substring(v_max,2,1) = '9' or substring(v_max,2,1) = '4' then
            v_max = (cast(v_max as integer) + 1)::text;
        end if;
        v_lim_f := ')';
    end if;

    IF v_min IS NOT NULL THEN
        RETURN '[' || v_min || ',' || v_max || v_lim_f;
    END IF;

    -- 2) Faixa concatenada: 1019, 1629, 5559
    SELECT
        m[1], m[2]
    INTO
        v_min, v_max
    FROM regexp_matches(
        texto,
        '(?<!\d)(\d{2})(\d{2})(?!\d)'
    ) AS m
    LIMIT 1;

    IF v_min > v_max THEN
        RETURN null;
    end if;

    if v_max = '99' THEN
        v_lim_f := ']';
    else
        if substring(v_max,2,1) = '9' or substring(v_max,2,1) = '4' then
            v_max = (cast(v_max as integer) + 1)::text;
        end if;
        v_lim_f := ')';
    end if;

    IF v_min IS NOT NULL THEN
        RETURN '[' || v_min || ',' || v_max || v_lim_f;
    END IF;

    -- 3) Faixa aberta: 60+, 70 +
    SELECT
        m[1]
    INTO
        v_min
    FROM regexp_matches(
        texto,
        '(?<!\d)(\d{2})\s*\+(?!\d)'
    ) AS m
    LIMIT 1;

    IF v_min IS NOT NULL THEN
        RETURN '[' || v_min || ',99]';
    END IF;

    -- Nenhuma faixa encontrada
    RETURN NULL;
END;
$function$
